-- PT109-S3-Q1. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT109-S3-Q1$batch03$ AND q.stimulus=$batch03$North American eastern white cedars grow both on cliff faces and in forests. Cedars growing on exposed cliff faces receive very few nutrients, and rarely grow bigger than one-tenth the height of cedars growing in forests, where they benefit from moisture and good soil. Yet few eastern white cedars found in forests are as old as four hundred years, while many on cliff faces are more than five hundred years old.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the difference in the ages of the cedars on cliff faces and those in forests?$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT109-S3-Q1$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT109-S3-Q1$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Forest cedars get water and good soil and grow ten times taller than cliff cedars.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Cliff cedars often live past 500 years while few forest cedars reach 400?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Better growing conditions do not guarantee a longer life. Something must cut forest trees' lives short or protect cliff trees. Ask what kills trees: fire, logging, disease, storms. We need one that hits the forest but not the cliff.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a threat in the forest that cliff cedars escape.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT109-S3-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Cliffs resembling other sparse places tells us nothing about why trees there live longer than forest trees.$batch03$), ($batch03$B$batch03$, $batch03$Fires are frequent where these cedars grow, and they reach forests but not cliff faces. Forest cedars burn before they get old; cliff cedars survive.$batch03$), ($batch03$C$batch03$, $batch03$Losing bark after a few hundred years would happen to old cedars wherever they grow. It does not separate cliff from forest.$batch03$), ($batch03$D$batch03$, $batch03$This explains why cliff cedars stay short. The puzzle is why they live longer, and height limits say nothing about age.$batch03$), ($batch03$E$batch03$, $batch03$Occasional furniture use might lead to some cutting, but the choice does not say forest cedars are cut more than cliff cedars. It does not explain the age gap.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT109-S3-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
